def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = sum(1 for _, o in history if o == 'D')

    if n > 0 and opp_defects == n:
        return 'D'

    if n >= 99:
        return 'D'

    if n < 4:
        return 'C'
    if n == 4:
        return 'D'

    test_my = history[4][0]
    test_opp = history[4][1]

    if n >= 6:
        tft_score = 0
        for i in range(1, n):
            if history[i][1] == history[i-1][0]:
                tft_score += 1
        if tft_score == n - 1:
            return 'C'

    if test_my == 'D' and test_opp == 'C' and opp_defects == 0:
        if n >= 98:
            return 'D'
        rounds_since_defect = 0
        for i in range(n-1, -1, -1):
            if history[i][0] == 'D':
                break
            rounds_since_defect += 1
        if rounds_since_defect >= 3:
            return 'D'
        return 'C'
    else:
        if opp_defects > n * 0.5:
            return 'D'
        last_m, last_o = history[-1]
        if last_o == 'D':
            if last_m == 'D':
                if rng.random() < 0.2:
                    return 'C'
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        else:
            return 'C'
